    let startTime = performance.now();

    function update(now) {
        const elapsed = now - startTime;
        const progress = Math.min(elapsed / duration, 1);
        // Ease out
        const easedProgress = 1 - Math.pow(1 - progress, 3);
        personMesh.position.z = startX + (targetZ - startX) * easedProgress;

        if (progress < 1) {
