    elevatorCar.rightDoor.position.set(SHAFT_WIDTH / 4 - 0.5, FLOOR_HEIGHT * 2 / 2, -SHAFT_DEPTH / 4);
    car.add(elevatorCar.rightDoor);

    return car;
}

