    for (let side of [-1, 1]) {
        const wallGeo = new THREE.BoxGeometry(1, FLOOR_HEIGHT * 2, SHAFT_DEPTH - 1);
        const wallMat = new THREE.MeshBasicMaterial({ color: 0x9999ff, transparent: true, opacity: 0.3 });
